            "extra": "Run: https://github.com/ROCm/ATOM/actions/runs/30701773314 | docker_image=rocm/atom-dev:latest | precision=MXFP4 | display_topology=1P1D-TP4 | perf_point=%7B%22backend%22%3A%22atomesh-atom%22%2C%22benchmark_kind%22%3A%22aiperf_agentic%22%2C%22chart_group%22%3A%22atomesh-model-performance%22%2C%22chart_label%22%3A%22MI355X%20%28atomesh-atom%20MXFP4%29%22%2C%22client_bench%22%3A%22inferencemax%20bench%22%2C%22completed%22%3A324%2C%22concurrency%22%3A48%2C%22config_label%22%3A%22mi355x_atomesh-atom_mxfp4_1p1d_tp4%22%2C%22decode_dpa%22%3Afalse%2C%22decode_tp%22%3A4%2C%22decode_workers%22%3A1%2C%22duration%22%3A3566.1844%2C%22e2el_ms%22%3A677752.8182%2C%22e2el_p99%22%3A938742.2492%2C%22hardware%22%3A%22mi355x%22%2C%22image%22%3A%22rocm%2Fatom-dev%3Alatest%22%2C%22input_tput%22%3A12207.6051%2C%22input_tput_per_gpu%22%3A3051.9013%2C%22interactivity%22%3A80.0011%2C%22isl%22%3A1048576%2C%22itl_ms%22%3A13.7462%2C%22median_e2el_ms%22%3A838361.6171%2C%22median_itl_ms%22%3A12.4998%2C%22median_tpot_ms%22%3A12.4998%2C%22median_ttft_ms%22%3A831284.2613%2C%22model%22%3A%22GLM-5.2-MXFP4%22%2C%22num_decode_gpu%22%3A4%2C%22num_prefill_gpu%22%3A4%2C%22osl%22%3A1024%2C%22output_tput%22%3A74.9483%2C%22output_tput_per_gpu%22%3A18.7371%2C%22precision%22%3A%22mxfp4%22%2C%22prefill_dpa%22%3Afalse%2C%22prefill_tp%22%3A4%2C%22prefill_workers%22%3A1%2C%22public_dataset%22%3A%22semianalysis_cc_traces_weka_062126%22%2C%22ratio%22%3A0.8%2C%22req_tput%22%3A0.0824%2C%22rocm%22%3A%22%22%2C%22run_id%22%3A%22pd-atom-GLM-5.2-MXFP4-1p1d-isl1048576-osl1024-conc48-0.8%22%2C%22run_url%22%3A%22https%3A%2F%2Fgithub.com%2FROCm%2FATOM%2Factions%2Fruns%2F30701773314%22%2C%22scenario%22%3A%22inferencex-agentx-mvp%22%2C%22slurm_job%22%3A%22%22%2C%22source%22%3A%22ATOMesh%22%2C%22total_gpu%22%3A8%2C%22total_tput%22%3A12282.5534%2C%22tpot_ms%22%3A13.7462%2C%22tpot_p99%22%3A23.0912%2C%22tput_per_gpu%22%3A1535.3192%2C%22ttft_ms%22%3A664155.4539%2C%22ttft_p99%22%3A865435.5261%7D"
